ruleContent.content:
@css:.tab,.pagebar:nth-child(1),[id^="comment_"],[id^="reply_"] script@html
<js>
java.log(result)
if(baseUrl.match(/page=\d+/)){
result=result
}else{
result="";
}
</js>
<js>
allpage=String(java.getString("@@class.num@text||class.pager.-2@text||class.pager.0@text")).match(/(\d+)/)?.[1];
result
.replace(/发表时间：/g,'\n⌚️')
.replace(/(№\d+)/g,'———————\n$1')
.replace(/<img src=".*?agree\.png">.*?numstr">([^<]+)<\/span>/g,'👍$1')
.replace(/<img.*?src=".*?agree_not\.png">.*?numstr">([^<]+)<\/span>/g,'👎$1')
.replace(/(评论共)<span class="redtext">/g,'📝$1')
.replace(/(当前显示第)/g,'共'+allpage+'页，$1')
.replace(/<span.*?>章评<\/span>|<span.*?>段评<\/span>|<img.*?src=".*?\/agree(?:_not)?\.png">/g,'')
.replace(/<br><span id="mormalreply_\d+"><span.*?><img .*?src="https?:\/\/i9-static.jjwxc.net.*?".*?><\/span><\/span>\s+<div class="readcontrolbar commentagreestyle".*?>/g,'')
.replace(/document.write\(showReplyList\((\[[\s\S]+?\]),.*?\)\);/g,function(m,r){
    let h = "";
    let arr = JSON.parse(r);
	for(let i = 0;i<arr.length;i++){
        let d = arr[i];             
        h += `[${d.floor}楼] 📜${d.commentauthor}${d.subscriptionicon.replace(/style='.*?'/g,'').replace(/src=(.*?) \//g,'src="https:$1"')}
　　⌚️${d.commentdate} ${d.agreenum!=0?"👍"+d.agreenum:""} ${d.disagreenum!=0?"👎"+d.disagreenum:""}<br>${d.commentbody}<br>`;
    }	
    return h
})
</js>

ruleContent.replaceRegex:
@js:
result.replace(/\[-收起\]|所评章节：\d+|评论：《.*?》|为营造更好的评论环境，.*|.*\[投诉\].*|<img.*?评论按回复时间倒序| 触发了您设置的屏蔽词和不再看TA，当前页面评论和回复已经为您屏蔽共\d+条|评论按回复时间正序.*|<img src=".*?66baeed24ae82_531.png">kswl|<img src=".*?66baeeb282db3_126.png">嗑到了|<img src=".*?nutrition_icon.png.*?">.*\s|.*?用户所发评论将在审核通过后显示！|<img src=".*?kingtickets_\d+.*?">.*?(?:手榴|月票|霸王票|小天使|火箭炮|深水鱼雷|浅水炸弹|地雷|营养液).*\s/g,'')
.replace(/）》\s+打分/g,' 打分')
.replace(/(№\d+)\s*网友：/g,'$1 👤')
.replace(/№\d+.*?\s*⌚️\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\s*·*\s*[👍\d]*\s*———————/g,'')
.replace(/№\d+.*?\s*⌚️\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\s*·*\s*[👍\d]*$/,'')
.replace(
  /(⌚️\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})([\s\S]*?)(👍\d+|👎\d+|(👍\d+ 👎\d+))/g,
  "$1 $3$2"
);

ruleToc.chapterList:
$.chapterlist
<js>
if(result=="[]"){
allpage=String(java.getString("@@class.num@text||class.redtext@text||class.pager.-2@text||class.pager.0@text")).match(/(\d+)/)?.[1]??0;
result = [];
for(i=1;i<=allpage;i++){
result.push({
	chaptername:"第"+i+"页",
	url:baseUrl.replace(/&page=\d+/g,'')+"&page="+i
	});
}
result = JSON.stringify(result)
	}
result
</js>
