function test(e) {
    if (e == undefined) {
        return java.log('\n' + JSON.stringify($$$['urls'], null, '\t')) + login('【源站输出提示】' + n(2) + k(3) + '源站已打印完毕，请到日志查看   ');
    }
    if (e == 0) {
        login('【初始化提示】' + n(2) + k(17) + '已恢复默认随机接口                 ');
        return put(original);
    }
    date1 = new Date().getTime();
    code = java.connect($$$.urls[e]).code();
    date2 = new Date().getTime();
    t = date2 - date1;
    time = t / 1000 + 's';
    c = String(code).indexOf('200');
    logTime = '【' + name(e) + '】\n┋┋\n' + '解析时间：' + time;
    if (c == -1 || t > 5000) {
        return login('【访问失败提示】' + n(2) + '┏┅━┅━┅━┅━┅━┅━┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♣️源站已失效(可能被墙)♣️\n┋┋\n请更新网址/切换源站/切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅━┅━┅━┅━┅┛');
    } else if (t < 1000) {
        return login('【网络环境优良】' + n(2) + '┏┅━┅━┅━┅━┅━┅━┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n❤️延迟低，推荐使用此站❤️\n┋┋\n网络环境优良，请继续保持状态\n┋┋' + '\n┗┅━┅━┅━┅━┅━┅━┅━┅━┅┛');
    } else if (t >= 1000 && t < 2000) {
        return login('【网络环境一般】' + n(2) + '┏┅━┅━┅━┅━┅━┅━┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♦️延迟一般，勉强可使用♦️\n┋┋\n请切换其他源站或切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅━┅━┅━┅━┅┛');
    } else if (t >= 2000 && t < 5000) {
        return login('【网络环境堪忧】' + n(2) + '┏┅━┅━┅━┅━┅━┅━┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♠延迟过高，不建议使用♠\n┋┋\n请切换其他源站或切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅━┅━┅━┅━┅┛');
    }
}
function put(data) {
    return source.setVariable(JSON.stringify(data, null, '\t'));
}
function name(e) {
    if (e == undefined) {
        e = 0;
    }
    return '  ' + x[e] + ' ' + $$$['urls'][e];
}
function login(e) {
    if (e == undefined) {
        return;
    }
    java.longToast(e);
}
function n(e) {
    n = '\n';
    for (m = 1; m < e; m++) {
        n = n + '\n';
    }
    return n;
}
function k(e) {
    k = ' ';
    for (q = 1; q < e; q++) {
        k = k + ' ';
    }
    return k;
}
function l(e) {
    l = '';
    for (o = 1; o < e; o++) {
        l = l + '';
    }
    return l;
}
function look(e) {
    if (e == 0) {
        return login('【查看当前源站】\n\n┏┅━┅━┅━┅━┅━┅━┅━┅━┅┓\n┋┋' + ('\n ' + '📌' + name($$$.ci0)) + '\n┋┋' + '\n┗┅━┅━┅━┅━┅━┅━┅━┅━┅┛');
