@js:
function spArr(arr, num){
  newArr = [];
	for( i = 0; i < arr.length;){
		newArr.push(arr.slice(i, i += num));
	}
	return newArr
}

res = JSON.parse(result).data;
item_list = spArr(res["item_list"], 100);
let v = [];
let array = [];
let book_id = res.book_info.book_id;
for( i = 0; i < item_list.length; i ++){
	  response = java.ajax('https://novel.snssdk.com/api/novel/book/directory/detail/v1/?item_ids='+item_list[i]);
	  if((book_id=="7182286100432423976") && (item_list[i].includes("7211874965795602984"))){
        response = response.replace("\\微笑","😊");
        }
	   data = JSON.parse(response).data;  

		data.forEach($=> {				

			V = $.volume_name;			
		if(v[v.length-1]!=V&&!/^\s*$/.test(V)){
			 v.push(V);
				array.push({
						name: "🏮〖"+V+"〗🏮",
						url: null,
						volume: true
					})
			}

		array.push({
			name: $.title,
			url:  `data:;base64,${java.base64Encode($.item_id)},{"type":"fqnovel"}`,
			info: ((Number(V)==0?"第一卷：默认":V)+' 📍 '+java.timeFormatUTC($.first_pass_time*1000,'yyyy-MM-dd HH:mm',0)+' 📍'+$.chapter_word_number+'字')	
	})
	})			
}
v.length<2?array.filter($=>!$.volume):array;

